def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Calculate the ratio of smaller IDs to total containers in the stack
    if SH == 0:
        ratio_smaller = 0
    else:
        ratio_smaller = RI / SH
    # Calculate the fraction of unknown IDs in the stack
    if DIFF == 0:
        unknown_fraction = 0
    else:
        unknown_fraction = (DIFF - CUR) / DIFF
    # Combine the metrics into a priority score
    priority = ratio_smaller + unknown_fraction * (1 - EMP / SH) if SH != 0 else 0
    return priority
